const raw = $input.first().json.candidates[0].content.parts[0].text.replace(/```json|```/g,'').trim();
const d = JSON.parse(raw);
const wh = $('Webhook').first().json.body;
return [{json:{...d, email: wh.email || '', meeting: wh.meeting || 'Meeting', date: new Date().toISOString().slice(0,10)}}];

const rows = $input.all().map(item => item.json);
const today = new Date().toISOString().slice(0, 10);
const tasks = rows.map((row, index) => {
  const deadline = row.Deadline || row.deadline || 'TBD';
  const rawStatus = row.Status || row.status || 'Open';
  const status = rawStatus === 'Open' ? 'Pending' : rawStatus;
  const deadlineTime = Date.parse(deadline);
  return {task: row.Task || row.task || '', owner: row.Owner || row.owner || 'Unassigned', deadline, priority: row.Priority || row.priority || 'Medium', status, meeting: row.Meeting || row.meeting || '', date: row.Date || row.date || '', email: row.Email || row.email || '', row_number: index + 2, overdue: status !== 'Completed' && Number.isFinite(deadlineTime) && deadlineTime < Date.now(), reminderNote: 'Daily reminders active'};
}).filter(task => task.task);
const counts = {all: tasks.length, pending: tasks.filter(t => t.status === 'Pending').length, inProgress: tasks.filter(t => t.status === 'In Progress').length, completed: tasks.filter(t => t.status === 'Completed').length, overdue: tasks.filter(t => t.overdue).length};
return [{json:{today, tasks, counts}}];

const today = new Date();
return $input.all().filter(item => {
  const row = item.json;
  const status = row.Status || row.status || 'Open';
  const email = row.Email || row.email || '';
  const deadline = Date.parse(row.Deadline || row.deadline || '');
  return email && status !== 'Completed' && Number.isFinite(deadline) && deadline <= today.getTime() + 86400000;
}).map(item => ({json: {...item.json, ownerEmail: item.json.Email || item.json.email, task: item.json.Task || item.json.task, deadline: item.json.Deadline || item.json.deadline, owner: item.json.Owner || item.json.owner || 'there'}}));
